   "motivo": "Texto mais direto."
  },
  {
   "campo": "resolucao.passos[2].conta",
   "depois": "J=1: 1×1 = 1\nJ=2: 2×2 = 4\nJ=3: 3×3 = 9\nJ=4: 4×4 = 16\nJ=5: 5×5 = 25\nJ=6: 6×6 = 36",
